def fetch_all(manifest, raw, pin=False, only=None, match=None, transport=None):
    """`match`: globs over each file's path under raw/; a file matching none is left untouched."""
    transport = transport or GoogleDrive()
    sources = load_manifest(manifest)
    for s in sources:
        if only and s['name'] not in only:
            continue
        if s['kind'] == 'file':
            if not _wanted(s['name'], match):
                continue
            digest = _fetch_one(s['drive_id'], os.path.join(raw, s['name']), s['sha256'], transport)
            if pin:
                s['sha256'] = digest
            continue
        files = s['files']
        if files is None or pin:
            # Re-listing only ever adds: a recorded entry keeps its checksum, so a file replaced
            # on Drive still fails verification instead of being silently re-pinned.
            files = list(files or [])
            known = {f['path'] for f in files}
            skip = s.get('skip', [])
            files += [{'path': p, 'drive_id': i, 'sha256': None}
                      for p, i in sorted(transport.list_folder(s['drive_id']))
                      if p not in known
                      and not any(fnmatch.fnmatch(os.path.basename(p), g) for g in skip)]
        for f in files:
            if not _wanted(f['path'], match):
                continue
            digest = _fetch_one(f['drive_id'], os.path.join(raw, f['path']), f['sha256'], transport)
            if pin:
                f['sha256'] = digest
        if pin:
            s['files'] = files
    if pin:
        save_manifest(manifest, sources)

