#!/usr/bin/env python3
"""Condense a Claude Code conversation-log JSONL into a compact, readable digest.

Usage: python3 condense_log.py <file.jsonl> [max_chars_per_field]
Reads from stdin if file is '-'.
"""
import json
import sys

MAXF = int(sys.argv[2]) if len(sys.argv) > 2 else 220


def trunc(s, n=MAXF):
    s = str(s)
    s = s.replace("\n", " \\n ")
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"


def render_content_block(b):
    if isinstance(b, str):
        return trunc(b)
    t = b.get("type")
    if t == "text":
        return trunc(b.get("text", ""))
    if t == "tool_use":
        return f"TOOL_USE {b.get('name')}({trunc(json.dumps(b.get('input', {})), 300)})"
    if t == "tool_result":
        content = b.get("content")
        if isinstance(content, list):
            content = " ".join(
                c.get("text", "") if isinstance(c, dict) else str(c) for c in content
            )
        err = " ERROR" if b.get("is_error") else ""
        return f"TOOL_RESULT{err} {trunc(content)}"
    if t == "thinking":
        return f"THINKING {trunc(b.get('thinking',''))}"
    return trunc(json.dumps(b))


def main():
    path = sys.argv[1]
    f = sys.stdin if path == "-" else open(path)
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            e = json.loads(line)
        except json.JSONDecodeError:
            continue
        ts = e.get("timestamp", "")
        typ = e.get("type", "")
        if typ == "attachment":
            att = e.get("attachment", {})
            hookname = att.get("hookName", "")
            print(f"[{ts}] ATTACHMENT hook={hookname}")
            continue
        msg = e.get("message")
        if not msg:
            print(f"[{ts}] {typ.upper()} (no message)")
            continue
        role = msg.get("role", typ)
        content = msg.get("content")
        if isinstance(content, str):
            print(f"[{ts}] {role}: {trunc(content)}")
        elif isinstance(content, list):
            for b in content:
                print(f"[{ts}] {role}: {render_content_block(b)}")
        else:
            print(f"[{ts}] {role}: {trunc(content)}")


if __name__ == "__main__":
    main()

